t = open(P, encoding="utf-8").read()
n = 0
for sid, txt in ADD.items():
    anchor = "判据 UNX-B2-S%03d-J1 闭合。" % sid
    assert t.count(anchor) == 1, sid
    t = t.replace(anchor, anchor + "【联签与红线】" + txt)
    n += 1
open(P, "w", encoding="utf-8").write(t)
